mapper.select:
SELECT * FROM equipment
WHERE deleted = 0

    AND (name LIKE CONCAT('%', #{query.keyword}, '%')
         OR code LIKE CONCAT('%', #{query.keyword}, '%')
         OR brand LIKE CONCAT('%', #{query.keyword}, '%'))


    AND name LIKE CONCAT('%', #{query.name}, '%')


    AND category = #{query.category}


    AND brand LIKE CONCAT('%', #{query.brand}, '%')


    AND status = #{query.status}


    AND create_time >= #{query.createTimeStart}


    AND create_time <= #{query.createTimeEnd}

ORDER BY create_time DESC
